import 'package:flutter/services.dart';
class SmsDispatch { const SmsDispatch(this.accepted,this.message); final bool accepted; final String message; }
class SmsService { static const _channel=MethodChannel('safehelm/sms'); Future<SmsDispatch> send(String phone,String body) async { try { final accepted=await _channel.invokeMethod<bool>('sendSms',{'phone':phone,'body':body})??false; return SmsDispatch(accepted,accepted?'Accepted by Android SMS system':'Android SMS system rejected request'); } on PlatformException catch(e){return SmsDispatch(false,e.message??'SMS unavailable');} } }
class EmergencyMessageBuilder { String build({required String type, required DateTime time, required double? latitude,required double? longitude,required bool test}) { final loc=latitude==null?'Current location unavailable':'$latitude, $longitude\nMap: https://maps.google.com/?q=$latitude,$longitude'; return '${test?'TEST ALERT — NOT AN EMERGENCY':'SAFEHELM EMERGENCY ALERT'}\n$type detected. Please contact the rider immediately.\nLocation: $loc\nTime: ${time.toLocal()}'; } }
